const _ = require('lodash');
const validator = require('validator');
const hash = require('object-hash');
const constant = require('./constant');

const EMPTY_ZSET_WITH_TOTAL = { data: [], total: 0 };

module.exports = (cache, module, retry) => {
  const common = {

    module,

    retry,

    isNotStrOrEmpty: value => {
      return !_.isString(value) || validator.isEmpty(value);
    },

    arrayToObj: array => {
      return _.fromPairs(_.chunk(array, 2));
    },

    mapToObj: map => {
      return _.fromPairs([ ...map ]);
    },

    objectToMap: obj => {
      const map = new Map();
      for (const k in obj) {
        /* istanbul ignore if */
        if (obj[k] === null || obj[k] === undefined) {
          // return null;
          continue;
        }
        map.set(k, obj[k]);
      }
      return map;
    },

    /**
     * @param key
     * @param type
     * @param forceMaster
     * @return {ver : ver , value : value}
     */
    getValueWithVer: function* (key, type, forceMaster) {
      const obj = yield cache.getStringWithVer(key, forceMaster);
      if (obj === undefined) {
        return undefined;
      }
      if (!obj || common.isNotStrOrEmpty(obj.value)) {
        return { ver: 1, value: null };
      }
      const value = JSON.parse(obj.value);
      /* istanbul ignore if */
      if (value._t !== type) {
        throw new Error(`${constant.ERROR.WRONGTYPE}, Key: ${key}, Operation Type: ${type}, Value Type: ${value._t}`);
      }
      return { ver: obj.ver, value: value.v };
    },

    /**
     * @param key
     * @param type
     * @param forceMaster
     * @return {ver : ver , value : value}
     */
    getValue: function* (key, type, forceMaseter = false) {
      let obj = yield cache.getString(key, forceMaseter);
      if (obj === undefined) {
        return undefined;
      }
      if (!obj || common.isNotStrOrEmpty(obj)) {
        return null;
      }
      obj = JSON.parse(obj);
      /* istanbul ignore if */
      if (obj._t !== type) {
        throw new Error(`${constant.ERROR.WRONGTYPE}, Key: ${key}, Operation Type: ${type}, Value Type: ${obj._t}`);
      }
      return obj.v;
    },

    toStringWithType: (value, type) => {
      return JSON.stringify({ _t: type, v: value });
    },

    convertToInt: value => {
      if (_.isString(value)) {
        if (validator.isInt(value)) {
          return Number.parseInt(value);
        }
      } else if (_.isNumber(value)) {
        if (Number.isInteger(value)) {
          return value;
        }
      }
      /* istanbul ignore next */
      throw new Error(`${constant.ERROR.NOT_INT}: ${value}`);
    },

    arrayToMap: array => {
      const map = new Map();
      for (let i = 0; i < array.length; i += 2) {
        /* istanbul ignore if */
        if (array[i] === null || array[i] === undefined || array[i + 1] === null || array[i + 1] === undefined) {
          return null;
        }
        map.set(array[i], array[i + 1]);
      }
      return map;
    },

    getFieldToArray: (fields, toString = false) => {
      /* istanbul ignore if */
      if (fields === null || fields === undefined || (_.isArray(fields) && fields.length === 0)) {
        return null;
      }
      /* istanbul ignore if */
      if (_.isString(fields)) {
        fields = [ fields ];
      } else if (_.isArray(fields)) {
        if (fields.length === 1) {
          const field = fields[0];
          if (_.isArray(field)) {
            return field;
          } else if (_.isSet(field)) {
            return Array.from(field);
          }
          fields = [ field ];
        }
      }
      if (toString) {
        fields = fields.map(field => {
          if (_.isString(field)) {
            return field;
          } else if (toString && _.isNumber(field)) {
            return field.toString();
          }
          return null;
        });
      }
      return fields;
    },

    getFieldToObj: fields => {
      /* istanbul ignore if */
      if (fields === null || fields === undefined || (_.isArray(fields) && fields.length === 0)) {
        return null;
      }
      let obj = null;
      if (_.isArray(fields)) {
        if (fields.length === 1) {
          const field = fields[0];
          if (_.isArray(field) && field.length > 0 && field.length % 2 === 0) {
            obj = common.arrayToObj(field);
          } else if (_.isMap(field)) {
            if (field.size !== 0) {
              obj = common.mapToObj(field);
            }
          } else if (_.isObject(field)) {
            obj = field;
          }
        } else if (fields.length % 2 === 0) {
          obj = common.arrayToObj(fields);
        }
      }
      if (obj === null || common.checkObjKvEmpty(obj)) {
        return null;
      }
      return obj;
    },

    checkObjKvEmpty: obj => {
      /* istanbul ignore if */
      if (!_.isObject(obj) || _.isEmpty(obj)) {
        return true;
      }
      for (const key in obj) {
        if (key === null || key === undefined || obj[key] === null || obj[key] === undefined) {
          return true;
        }
      }
      return false;
    },

    parseZSetArgu: function(argu, minIsBefore) {
      const keys = Array.from(argu);
      let const_count = 0;
      let withscores = false;
      let limit = false;
      for (let i = 1; i <= 2; i++) {
        if (_.isString(keys[i]) && keys[i].toLowerCase() === '-inf') {
          keys[i] = Number.MIN_SAFE_INTEGER;
        } else if (_.isString(keys[i]) && keys[i].toLowerCase() === '+inf') {
          keys[i] = Number.MAX_SAFE_INTEGER;
        }
      }
      if (keys[3] === constant.CONSTANT.WITHSCORES) {
        withscores = true;
        const_count++;
      }
      if (keys[3 + const_count] === constant.CONSTANT.LIMIT) {
        limit = true;
        const_count++;
      }
      return {
        min: minIsBefore ? keys[1] : keys[2],
        max: minIsBefore ? keys[2] : keys[1],
        withscores,
        limit,
        offset: limit ? common.convertToInt(keys[3 + const_count]) : 0,
        count: limit ? common.convertToInt(keys[4 + const_count]) : 0,
        forceMaster: keys[keys.length - 1],
      };
    },

    getTotal: function(total, skip, min, max) {
      if (min === Number.MIN_SAFE_INTEGER && max === Number.MAX_SAFE_INTEGER) {
        return total;
      }
      if (min !== Number.MIN_SAFE_INTEGER && max !== Number.MAX_SAFE_INTEGER) {
        return total;
      }
      return total - skip;
    },

    // eslint-disable-next-line no-unused-vars
    zrangebyscoreWithTotal: function* (key, MIN, MAX, WITHSCORES, LIMIT, OFFSET, COUNT) {
      let { min, max, withscores, limit, offset, count, forceMaster } = common.parseZSetArgu(arguments, true);
      /* istanbul ignore if */
      if (common.isNotStrOrEmpty(key) || (limit && (count === 0))) {
        return EMPTY_ZSET_WITH_TOTAL;
      }
      const origObj = yield common.getValue(key, constant.TYPE.ZSET, forceMaster);
      if (origObj === undefined) {
        return undefined;
      }
      if (origObj === null) {
        return EMPTY_ZSET_WITH_TOTAL;
      }
      const [ origSet, origHash, origDict ] = [ origObj.s, origObj.h, origObj.d ];
      let scoreArray = Object.keys(origSet);
      const result = [];

      if (scoreArray && scoreArray.length && scoreArray[scoreArray.length - 1] < 0) {
        scoreArray = _.sortBy(scoreArray, v => Number.parseInt(v));
      }

      let skip = 0;
      for (let i = 0; i < scoreArray.length; i++) {
        const score = common.convertToInt(scoreArray[i]);
        const memberArray = origSet[score];
        if (score > max) {
          break;
        }
        if (!memberArray || !memberArray.length || score < min) {
          skip += memberArray ? memberArray.length : 0;
          continue;
        }
        for (let j = 0; j < memberArray.length; j++) {
          if (limit && offset-- > 0) {
            skip++;
            continue;
          }
          if (!limit || count-- > 0) {
            const member = memberArray[j];
            if (origDict[member]) {
              result.push(origDict[member]);
            } else {
              result.push(member);
            }
            if (withscores) {
              result.push(common.convertToInt(score));
            }
          }
        }
      }
      return { data: result, total: common.getTotal(Object.keys(origHash).length, skip, min, max) };
    },

    // eslint-disable-next-line no-unused-vars
    zrevrangebyscoreWithTotal: function* (key, MAX, MIN, WITHSCORES, LIMIT, OFFSET, COUNT) {
      let { min, max, withscores, limit, offset, count, forceMaster } = common.parseZSetArgu(arguments, false);
      /* istanbul ignore if */
      if (common.isNotStrOrEmpty(key) || (limit && (count === 0))) {
        return EMPTY_ZSET_WITH_TOTAL;
      }
      const origObj = yield common.getValue(key, constant.TYPE.ZSET, forceMaster);
      if (origObj === undefined) {
        return undefined;
      }
      if (origObj === null) {
        return EMPTY_ZSET_WITH_TOTAL;
      }
      const [ origSet, origHash, origDict ] = [ origObj.s, origObj.h, origObj.d ];
      let scoreArray = Object.keys(origSet);
      const result = [];

      if (scoreArray && scoreArray.length && scoreArray[scoreArray.length - 1] < 0) {
        scoreArray = _.sortBy(scoreArray, v => Number.parseInt(v));
      }

      let skip = 0;
      for (let i = scoreArray.length - 1; i >= 0; i--) {
        const score = common.convertToInt(scoreArray[i]);
        const memberArray = origSet[score];
        if (score < min) {
          break;
        }
        if (!memberArray || !memberArray.length || score > max) {
          skip += memberArray ? memberArray.length : 0;
          continue;
        }
        for (let j = memberArray.length - 1; j >= 0; j--) {
          if (limit && offset-- > 0) {
            skip++;
            continue;
          }
          if (!limit || count-- > 0) {
            const member = memberArray[j];
            if (origDict[member]) {
              result.push(origDict[member]);
            } else {
              result.push(member);
            }
            if (withscores) {
              result.push(common.convertToInt(score));
            }
          }
        }
      }
      return { data: result, total: common.getTotal(Object.keys(origHash).length, skip, min, max) };
    },

    zAddOrIncrement: function* (isIncrement = false, key, ...kvs) {
      const newDict = {};
      let newObj;
      /* istanbul ignore if */
      if (common.isNotStrOrEmpty(key) || kvs.length === 0 || (kvs.length >= 2 && kvs.length % 2 !== 0)) {
        return false;
      } else if (kvs.length === 1) {
        const kv = kvs[0];
        if (_.isMap(kv)) {
          newObj = new Map();
          kv.forEach((score, member) => {
            if (_.isObject(member)) {
              const hash = common.hash(member);
              newObj.set(hash, common.convertToInt(score));
              newDict[hash] = member;
            } else {
              newObj.set(member, common.convertToInt(score));
            }
          });
        } else if (_.isObject(kv)) {
          /* istanbul ignore if */
          if (_.find(Object.keys(kv), '[object Object]')) {
            return false;
          }
          newObj = common.objectToMap(kv);
          newObj.forEach(function(value, key) {
            newObj.set(key, common.convertToInt(value));
          });
        }
      } else {
        newObj = new Map();
        for (let i = 0; i < kvs.length; i += 2) {
          const [ score, member ] = [ common.convertToInt(kvs[i]), kvs[i + 1] ];
          /* istanbul ignore if */
          if (member === null || member === undefined) {
            return false;
          } else if (_.isObject(member)) {
            const hash = common.hash(member);
            newObj.set(hash, common.convertToInt(score));
            newDict[hash] = member;
          } else {
            newObj.set(member, common.convertToInt(score));
          }
        }
      }
      if (!newObj.size) {
        return true;
      }
      for (let i = 0; i < common.retry; i++) {
        const objVer = yield common.getValueWithVer(key, constant.TYPE.ZSET, constant.CONSTANT.FORCEMASTER);
        let origObj;
        if (objVer === null || objVer.value === null) {
          origObj = { s: {}, h: {}, d: {} };
        } else {
          origObj = objVer.value;
        }
        const [ origSet, origHash, origDict ] = [ origObj.s, origObj.h, origObj.d ];

        let newScore;
        for (const [ key, value ] of newObj.entries()) {
          const member = key;
          const score = value;
          let origScore = origHash[member];
          newScore = score;
          if (origScore !== null && origScore !== undefined) {
            origScore = common.convertToInt(origScore);
            if (isIncrement) {
              newScore = origScore + score;
            }
            if (origScore === newScore) {
              continue;
            }
            const memberArray = origSet[origScore];
            if (_.isArray(memberArray) && memberArray.length > 0) {
              const memberSet = new Set(memberArray);
              memberSet.delete(member);
              if (memberSet.size) {
                origSet[origScore] = Array.from(memberSet);
              } else {
                delete origSet[origScore];
              }
            }
          }
          if (!origSet[newScore]) {
            origSet[newScore] = [];
          }
          origSet[newScore].push(member);
          origSet[newScore] = origSet[newScore];
          origHash[member] = newScore;
        }
        for (const score in origSet) {
          origSet[score] = origSet[score].sort();
        }
        // 对score对象进行重新排序,修复score值过大时没有自动排序的bug
        // eslint-disable-next-line no-return-assign,no-sequences
        origObj.s = Object.keys(origSet).sort().reduce((r, k) => (r[k] = origSet[k], r), {});
        origObj.d = _.extend(origDict, newDict);
        if (yield common.setStringEx(key, common.toStringWithType(origObj, constant.TYPE.ZSET), objVer.ver)) {
          return isIncrement ? newScore : true;
        }
      }
      /* istanbul ignore next */
      return false;
    },

    lock: cache.lock,

    hash: hash.MD5,
  };

  // export all operation of cache.js
  for (const operation in cache) {
    const fn = cache[operation];
    if (_.isFunction(fn)) {
      common[operation] = fn;
    }
  }

  return common;

};
